6: # JWT Security
7: 
8: You are an expert in JSON Web Token (JWT) security implementation. Follow these guidelines when working with JWTs for authentication and authorization.
9: 
10: ## Core Principles
11: 
12: - JWTs are not inherently secure - security depends on implementation
13: - Always validate tokens server-side, even for internal services
14: - Use asymmetric signing (RS256, ES256) when possible
15: - Keep tokens short-lived and implement proper refresh mechanisms
16: - Never store sensitive data in JWT payloads
17: 
18: ## Token Structure
19: 
20: A JWT consists of three parts: Header, Payload, and Signature.
21: 
22: ```
23: header.payload.signature
24: ```
25: 
26: ### Header Best Practices
27: 
28: ```json
29: {
30:   "alg": "RS256",
31:   "typ": "JWT",
32:   "kid": "key-identifier-for-rotation"
33: }
34: ```
35: 
36: - Always include `kid` (key ID) for key rotation support
37: - Use `typ: "JWT"` explicitly
38: - Never accept `alg: "none"`
39: 
40: ### Payload Best Practices
41: 
42: ```json
43: {
44:   "iss": "https://auth.example.com",
45:   "sub": "user-uuid-here",
46:   "aud": "https://api.example.com",
47:   "exp": 1704067200,
48:   "iat": 1704063600,
49:   "nbf": 1704063600,
50:   "jti": "unique-token-id"
51: }
52: ```
53: 
54: Required claims:
55: - `iss` (issuer): Who created the token
56: - `sub` (subject): Who the token represents
57: - `aud` (audience): Who the token is intended for
58: - `exp` (expiration): When the token expires
59: - `iat` (issued at): When the token was created
60: 
61: Recommended claims:
62: - `nbf` (not before): Token not valid before this time
63: - `jti` (JWT ID): Unique identifier for token revocation
64: 
65: ## Signing Algorithm Selection
66: 
67: ### Recommended: Asymmetric Algorithms
68: 
69: ```javascript
70: // RS256 - RSA with SHA-256 (most widely supported)
71: // ES256 - ECDSA with P-256 and SHA-256 (smaller keys)
72: // EdDSA - Edwards-curve Digital Signature Algorithm (most secure)
73: 
74: const ALLOWED_ALGORITHMS = ['RS256', 'ES256', 'EdDSA'];
75: ```
76: 
77: ### When Symmetric is Required
78: 
79: ```javascript
80: // HS256 - HMAC with SHA-256
81: // Only use with a strong secret (minimum 256 bits / 32 bytes)
82: const secret = crypto.randomBytes(64).toString('hex');
83: ```
84: 
85: ## Token Creation
86: 
87: ### Using RS256 (Recommended)
88: 
89: ```javascript
90: const jwt = require('jsonwebtoken');
91: const fs = require('fs');
92: 
93: const privateKey = fs.readFileSync('private.pem');
94: 
95: function createToken(userId, roles) {
96:   const payload = {
97:     sub: userId,
98:     roles: roles,
99:     // Keep custom claims minimal
100:   };
101: 
102:   const options = {
103:     algorithm: 'RS256',
104:     expiresIn: '15m', // Short-lived access tokens
105:     issuer: 'https://auth.example.com',
106:     audience: 'https://api.example.com',
107:     keyid: 'current-key-id',
108:   };
109: 
110:   return jwt.sign(payload, privateKey, options);
111: }
112: ```
113: 
114: ### Token Lifetime Guidelines
115: 
116: ```javascript
117: const TOKEN_LIFETIMES = {
118:   accessToken: '15m',      // 15 minutes max
119:   refreshToken: '7d',      // 7 days with rotation
120:   idToken: '1h',           // 1 hour
121:   passwordReset: '15m',    // 15 minutes
122:   emailVerification: '24h', // 24 hours
123: };
124: ```
125: 
126: ## Token Validation
127: 
128: ### Complete Validation Example
129: 
130: ```javascript
131: const jwt = require('jsonwebtoken');
132: const jwksClient = require('jwks-rsa');
133: 
134: // JWKS client for fetching public keys
135: const client = jwksClient({
136:   jwksUri: 'https://auth.example.com/.well-known/jwks.json',
137:   cache: true,
138:   cacheMaxAge: 600000, // 10 minutes
139:   rateLimit: true,
140:   jwksRequestsPerMinute: 10,
141: });
142: 
143: async function validateToken(token) {
144:   // 1. Decode header without verification to get kid
145:   const decoded = jwt.decode(token, { complete: true });
146: 
147:   if (!decoded) {
148:     throw new Error('Invalid token format');
149:   }
150: 
151:   // 2. Validate algorithm against whitelist
152:   if (!ALLOWED_ALGORITHMS.includes(decoded.header.alg)) {
153:     throw new Error(`Algorithm ${decoded.header.alg} not allowed`);
154:   }
155: 
156:   // 3. Get signing key
157:   const key = await client.getSigningKey(decoded.header.kid);
158:   const publicKey = key.getPublicKey();
159: 
160:   // 4. Verify signature and claims
161:   const verified = jwt.verify(token, publicKey, {
162:     algorithms: ALLOWED_ALGORITHMS, // Whitelist algorithms
163:     issuer: 'https://auth.example.com',
164:     audience: 'https://api.example.com',
165:     clockTolerance: 30, // 30 seconds clock skew tolerance
166:   });
167: 
168:   return verified;
169: }
170: ```
171: 
172: ### Validation Checklist
173: 
174: ```javascript
175: function validateTokenClaims(decoded) {
176:   const now = Math.floor(Date.now() / 1000);
177: 
178:   // 1. Check expiration
179:   if (decoded.exp && decoded.exp < now) {
180:     throw new Error('Token expired');
181:   }
182: 
183:   // 2. Check not before
184:   if (decoded.nbf && decoded.nbf > now) {
185:     throw new Error('Token not yet valid');
186:   }
187: 
188:   // 3. Check issuer
189:   if (decoded.iss !== EXPECTED_ISSUER) {
190:     throw new Error('Invalid issuer');
191:   }
192: 
193:   // 4. Check audience
194:   const audiences = Array.isArray(decoded.aud) ? decoded.aud : [decoded.aud];
195:   if (!audiences.includes(EXPECTED_AUDIENCE)) {
196:     throw new Error('Invalid audience');
197:   }
198: 
199:   // 5. Check required claims exist
200:   if (!decoded.sub) {
201:     throw new Error('Missing subject claim');
202:   }
203: 
204:   return true;
205: }
206: ```
207: 
208: ## Security Vulnerabilities to Prevent
209: 
210: ### 1. Algorithm Confusion Attack
211: 
212: ```javascript
213: // WRONG: Accepting any algorithm
214: jwt.verify(token, secret); // Vulnerable!
215: 
216: // CORRECT: Whitelist allowed algorithms
217: jwt.verify(token, key, { algorithms: ['RS256'] });
218: ```
219: 
220: ### 2. None Algorithm Attack
221: 
222: ```javascript
223: // Always reject 'none' algorithm
224: if (decoded.header.alg === 'none' || decoded.header.alg.toLowerCase() === 'none') {
225:   throw new Error('Algorithm none is not allowed');
226: }
227: ```
228: 
229: ### 3. Key Confusion (RS256 vs HS256)
230: 
231: ```javascript
232: // When using asymmetric keys, never allow symmetric algorithms
233: const ASYMMETRIC_ONLY = ['RS256', 'RS384', 'RS512', 'ES256', 'ES384', 'ES512', 'EdDSA'];
234: 
235: jwt.verify(token, publicKey, { algorithms: ASYMMETRIC_ONLY });
236: ```
237: 
238: ### 4. Weak HMAC Secrets
239: 
240: ```javascript
241: // Minimum 256-bit (32 byte) secret for HS256
242: // Minimum 384-bit (48 byte) secret for HS384
243: // Minimum 512-bit (64 byte) secret for HS512
244: 
245: function generateHmacSecret(algorithm) {
246:   const bits = parseInt(algorithm.slice(2)); // HS256 -> 256
247:   const bytes = bits / 8;
248:   return crypto.randomBytes(Math.max(bytes, 32)).toString('hex');
249: }
250: ```
251: 
252: ## Token Storage
253: 
254: ### Browser Storage Security
255: 
256: ```javascript
257: // Best: HttpOnly cookie (requires backend support)
258: // Server sets:
259: res.cookie('access_token', token, {
260:   httpOnly: true,
261:   secure: true,
262:   sameSite: 'strict',
263:   maxAge: 900000, // 15 minutes
264: });
265: 
266: // Acceptable: In-memory (lost on refresh)
267: let accessToken = null;
268: function setToken(token) {
269:   accessToken = token;
270: }
271: 
272: // Avoid: localStorage (vulnerable to XSS)
273: // Avoid: sessionStorage for sensitive tokens
274: ```
275: 
276: ### Token Transmission
277: 
278: ```javascript
279: // Always use Authorization header
280: fetch('/api/resource', {
281:   headers: {
282:     Authorization: `Bearer ${accessToken}`,
283:   },
284: });
285: 
286: // Never put tokens in URLs (logged, cached, visible in history)
287: // WRONG: /api/resource?token=eyJ...
288: ```
289: 
290: ## Refresh Token Implementation
291: 
292: ```javascript
293: // Refresh tokens should be:
294: // 1. Stored securely (httpOnly cookie or secure server-side storage)
295: // 2. Rotated on each use
296: // 3. Bound to the client (if possible)
297: 
298: async function refreshAccessToken(refreshToken) {
299:   // Validate refresh token
300:   const decoded = await validateRefreshToken(refreshToken);
301: 
302:   // Check if token has been revoked
303:   const isRevoked = await checkTokenRevocation(decoded.jti);
304:   if (isRevoked) {
305:     throw new Error('Refresh token has been revoked');
306:   }
307: 
308:   // Generate new tokens
309:   const newAccessToken = createAccessToken(decoded.sub);
310:   const newRefreshToken = createRefreshToken(decoded.sub);
311: 
312:   // Revoke old refresh token (rotation)
313:   await revokeToken(decoded.jti);
314: 
315:   return { accessToken: newAccessToken, refreshToken: newRefreshToken };
316: }
317: ```
318: 
319: ## Token Revocation
320: 
321: ```javascript
322: // Maintain a revocation list for early token invalidation
323: const revokedTokens = new Set(); // Use Redis in production
324: 
325: function revokeToken(jti) {
326:   revokedTokens.add(jti);
327: }
328: 
329: function isTokenRevoked(jti) {
330:   return revokedTokens.has(jti);
331: }
332: 
333: // Include revocation check in validation
334: async function validateToken(token) {
335:   const decoded = jwt.verify(token, key, options);
336: 
337:   if (decoded.jti && isTokenRevoked(decoded.jti)) {
338:     throw new Error('Token has been revoked');
339:   }
340: 
341:   return decoded;
342: }
343: ```
344: 
345: ## Key Rotation
346: 
347: ```javascript
348: // Support multiple keys during rotation
349: const keyStore = {
350:   'key-2024-01': { /* current key */ },
351:   'key-2023-12': { /* previous key, still valid */ },
352: };
353: 
354: // JWKS endpoint should expose all valid public keys
355: app.get('/.well-known/jwks.json', (req, res) => {
356:   const keys = Object.entries(keyStore).map(([kid, key]) => ({
357:     kid,
358:     kty: 'RSA',
359:     use: 'sig',
360:     alg: 'RS256',
361:     n: key.publicKey.n,
362:     e: key.publicKey.e,
363:   }));
364: 
365:   res.json({ keys });
366: });
367: ```
368: 
369: ## Express Middleware Example
370: 
371: ```javascript
372: const expressJwt = require('express-jwt');
373: const jwksRsa = require('jwks-rsa');
374: 
375: const jwtMiddleware = expressJwt({
376:   secret: jwksRsa.expressJwtSecret({
377:     cache: true,
378:     rateLimit: true,
379:     jwksRequestsPerMinute: 5,
380:     jwksUri: 'https://auth.example.com/.well-known/jwks.json',
381:   }),
382:   audience: 'https://api.example.com',
383:   issuer: 'https://auth.example.com',
384:   algorithms: ['RS256'],
385: });
386: 
387: // Protected route
388: app.get('/api/protected', jwtMiddleware, (req, res) => {
389:   // req.auth contains the decoded token
390:   res.json({ user: req.auth.sub });
391: });
392: ```
393: 
394: ## Testing
395: 
396: ```javascript
397: describe('JWT Validation', () => {
398:   it('should reject expired tokens', async () => {
399:     const expiredToken = createToken({ exp: Math.floor(Date.now() / 1000) - 3600 });
400:     await expect(validateToken(expiredToken)).rejects.toThrow('expired');
401:   });
402: 
403:   it('should reject tokens with wrong issuer', async () => {
404:     const wrongIssuer = createToken({ iss: 'https://evil.com' });
405:     await expect(validateToken(wrongIssuer)).rejects.toThrow('issuer');
406:   });
407: 
408:   it('should reject none algorithm', async () => {
409:     const noneAlg = 'eyJhbGciOiJub25lIiwidHlwIjoiSldUIn0.eyJzdWIiOiIxMjM0NTY3ODkwIn0.';
410:     await expect(validateToken(noneAlg)).rejects.toThrow('algorithm');
411:   });
412: });
413: ```
414: 
415: ## Common Anti-Patterns to Avoid
416: 
417: 1. Using JWTs for session management (prefer server-side sessions for web apps)
418: 2. Storing sensitive data in JWT payload (it's only encoded, not encrypted)
419: 3. Not validating all claims
420: 4. Using weak or hardcoded secrets
421: 5. Not implementing token expiration
422: 6. Trusting the algorithm header without validation
423: 7. Not implementing refresh token rotation
424: 8. Logging full tokens"}}
